package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type AuditEntry struct {
	Timestamp time.Time `bson:"timestamp"`
	Action    string    `bson:"action"`
	User      string    `bson:"user"`
	Query     string    `bson:"query"`
	Result    string    `bson:"result"`
}

type QueryFilter struct {
	Field    string `json:"field"`
	Operator string `json:"operator"`
	Value    string `json:"value"`
}

type SearchRequest struct {
	Collection string        `json:"collection"`
	Filters    []QueryFilter `json:"filters"`
	Requestor  string        `json:"requestor"`
}

var allowedOperators = map[string]bool{
	"eq":  true,
	"ne":  true,
	"gt":  true,
	"lt":  true,
	"gte": true,
	"lte": true,
}

var fieldNameRegex = regexp.MustCompile(`^[a-zA-Z][a-zA-Z0-9_.]{0,63}$`)

// maxBodyBytes limits the size of incoming request bodies to prevent
// memory-exhaustion DoS from arbitrarily large payloads.
const maxBodyBytes = 1 << 20 // 1 MiB

func sanitizeValue(val string) string {
	val = strings.ReplaceAll(val, "$", "")
	val = strings.ReplaceAll(val, "{", "")
	val = strings.ReplaceAll(val, "}", "")
	return val
}

func hashForAudit(input string) string {
	h := sha256.Sum256([]byte(input))
	return hex.EncodeToString(h[:])
}

func buildFilter(filters []QueryFilter) (bson.D, error) {
	result := bson.D{}
	for _, f := range filters {
		if !fieldNameRegex.MatchString(f.Field) {
			return nil, fmt.Errorf("invalid field name: %s", f.Field)
		}
		if !allowedOperators[f.Operator] {
			return nil, fmt.Errorf("invalid operator: %s", f.Operator)
		}
		cleanValue := sanitizeValue(f.Value)
		operatorKey := "$" + f.Operator
		result = append(result, bson.E{
			Key:   f.Field,
			Value: bson.D{{Key: operatorKey, Value: cleanValue}},
		})
	}
	return result, nil
}

func writeAuditLog(ctx context.Context, db *mongo.Database, entry AuditEntry) error {
	auditCol := db.Collection("audit_log")
	_, err := auditCol.InsertOne(ctx, entry)
	return err
}

func buildAuditQuery(filters []QueryFilter) string {
	parts := make([]string, 0, len(filters))
	for _, f := range filters {
		parts = append(parts, fmt.Sprintf("%s %s %s", f.Field, f.Operator, hashForAudit(f.Value)))
	}
	return strings.Join(parts, " AND ")
}

func performAuditedSearch(ctx context.Context, db *mongo.Database, req SearchRequest) ([]bson.M, error) {
	auditQuery := buildAuditQuery(req.Filters)

	filter, err := buildFilter(req.Filters)
	if err != nil {
		writeAuditLog(ctx, db, AuditEntry{
			Timestamp: time.Now(),
			Action:    "search_rejected",
			User:      req.Requestor,
			Query:     auditQuery,
			Result:    "validation_failed",
		})
		return nil, err
	}

	allowedCollections := map[string]bool{
		"products": true,
		"articles": true,
		"reviews":  true,
	}
	if !allowedCollections[req.Collection] {
		return nil, fmt.Errorf("collection not allowed: %s", req.Collection)
	}

	col := db.Collection(req.Collection)
	cursor, err := col.Find(ctx, filter)
	if err != nil {
		return nil, err
	}
	defer cursor.Close(ctx)

	var results []bson.M
	if err := cursor.All(ctx, &results); err != nil {
		return nil, err
	}

	writeAuditLog(ctx, db, AuditEntry{
		Timestamp: time.Now(),
		Action:    "search_executed",
		User:      req.Requestor,
		Query:     auditQuery,
		Result:    fmt.Sprintf("returned %d results", len(results)),
	})

	return results, nil
}

func searchHandler(db *mongo.Database) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		// Limit the size of the request body to prevent memory-exhaustion DoS.
		r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)

		var req SearchRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "invalid request body", http.StatusBadRequest)
			return
		}

		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()

		results, err := performAuditedSearch(ctx, db, req)
		if err != nil {
			http.Error(w, "request failed", http.StatusBadRequest)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(results)
	}
}

func auditSearchHandler(db *mongo.Database) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		user := r.URL.Query().Get("user")
		action := r.URL.Query().Get("action")

		if user == "" {
			http.Error(w, "user parameter required", http.StatusBadRequest)
			return
		}

		if !fieldNameRegex.MatchString(user) {
			http.Error(w, "invalid user parameter", http.StatusBadRequest)
			return
		}

		allowedActions := map[string]bool{
			"":                true,
			"search_executed": true,
			"search_rejected": true,
		}
		if !allowedActions[action] {
			http.Error(w, "invalid action parameter", http.StatusBadRequest)
			return
		}

		filter := bson.D{{Key: "user", Value: user}}
		if action != "" {
			filter = append(filter, bson.E{Key: "action", Value: action})
		}

		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()

		auditCol := db.Collection("audit_log")
		cursor, err := auditCol.Find(ctx, filter)
		if err != nil {
			http.Error(w, "query failed", http.StatusInternalServerError)
			return
		}
		defer cursor.Close(ctx)

		var entries []AuditEntry
		if err := cursor.All(ctx, &entries); err != nil {
			http.Error(w, "decode failed", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(entries)
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		log.Fatal(err)
	}
	defer client.Disconnect(ctx)

	db := client.Database("appdb")

	mux := http.NewServeMux()
	mux.HandleFunc("/api/search", searchHandler(db))
	mux.HandleFunc("/api/audit", auditSearchHandler(db))

	// Configure server-level timeouts to mitigate slow-client/Slowloris DoS.
	server := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       15 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	log.Println("Server starting on :8080")
	log.Fatal(server.ListenAndServe())
}
